package mz.bam.seeky.android;
import android.app.*;import android.os.*;import android.speech.tts.*;import java.util.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={SpeechServiceTest.ManualTts.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class SpeechPageFlowTest {
 SpeechPrefetchTest fixture;ReadAloudService service;
 @Before public void before()throws Exception{WorkspaceEpoch.value=0;WorkspaceEpoch.restoring=false;SleepTimer.cancel(RuntimeEnvironment.getApplication());SpeechServiceTest.ManualTts.texts.clear();SpeechServiceTest.ManualTts.queues.clear();SpeechServiceTest.ManualTts.silences.clear();SpeechServiceTest.ManualTts.gapIds.clear();SpeechServiceTest.ManualTts.silentFails=false;fixture=new SpeechPrefetchTest();fixture.setup();}
 void start()throws Exception{fixture.start("Segunda página pronta para continuar a leitura.");service=fixture.service;fixture.drain();}
 @After public void after(){fixture.close();SleepTimer.cancel(RuntimeEnvironment.getApplication());}
 @Test public void nextPageIsSentToTheEngineWhileTheCurrentPageStillPlays()throws Exception{start();assertEquals(0,service.part);assertTrue(service.cursor.pending.text.contains("Primeiro"));assertTrue("Next page must already be queued in the TTS engine",SpeechServiceTest.ManualTts.texts.stream().anyMatch(s->s.contains("Segunda página")));assertEquals(Arrays.asList(TextToSpeech.QUEUE_FLUSH,TextToSpeech.QUEUE_ADD),SpeechServiceTest.ManualTts.queues);}
 @Test public void automaticPageChangeDoesNotFlushTheVoiceQueue()throws Exception{start();String current=service.cursor.pending.id;service.progress.onDone(current);shadowOf(Looper.getMainLooper()).idle();fixture.drain();assertEquals(1,service.part);assertTrue(service.cursor.pending.text.contains("Segunda página"));assertEquals("One start plus one queued page, without resubmitting",2,SpeechServiceTest.ManualTts.queues.size());assertEquals(Integer.valueOf(TextToSpeech.QUEUE_ADD),SpeechServiceTest.ManualTts.queues.get(1));}
 @Test public void transitionUsesThePreparedVoiceEvenWhenTheDocumentWorkerIsBusy()throws Exception{start();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);service.worker.execute(()->{entered.countDown();try{release.await(20,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(10,TimeUnit.SECONDS));try{service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertFalse(service.loading);assertNotNull(service.cursor.pending);assertTrue(service.cursor.pending.text.contains("Segunda página"));assertEquals(2,SpeechServiceTest.ManualTts.texts.size());assertEquals(1,release.getCount());assertEquals(1,service.prefs.getInt("speech_part_"+fixture.uri,-1));}finally{release.countDown();fixture.drain();}}
 @Test public void nextStartBeforeThePreviousDoneCallbackCannotSkipOrRepeatText()throws Exception{start();String old=service.cursor.pending.id,next=service.queuedPage.cursor.pending.id;service.progress.onStart(next);service.progress.onDone(old);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(next,service.cursor.pending.id);service.progress.onRangeStart(next,3,9,0);shadowOf(Looper.getMainLooper()).idle();assertEquals(3,service.cursor.spoken);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());}
 @Test public void pauseCancelsTheNextPageAndLateCallbacksCannotAffectResumedSpeech()throws Exception{start();String cancelled=service.queuedPage.cursor.pending.id;service.pause("Pausado");assertNull(service.queuedPage);assertTrue(service.cursor.paused);service.resume();String resumed=service.cursor.pending.id;assertNotEquals(cancelled,resumed);service.progress.onStart(cancelled);service.progress.onRangeStart(cancelled,10,15,0);service.progress.onDone(cancelled);shadowOf(Looper.getMainLooper()).idle();assertEquals(0,service.part);assertEquals(resumed,service.cursor.pending.id);assertEquals(0,service.cursor.spoken);}
 @Test public void armingEndOfChapterAfterReadAheadStopsAtTheRequestedBoundary()throws Exception{start();SleepTimer.end(fixture.app,fixture.uri.toString(),0,0);shadowOf(Looper.getMainLooper()).idle();assertNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(0,service.part);assertTrue(service.cursor.paused);assertTrue(service.message.contains("Temporizador"));}
 @Test public void aHeadingAtTheEndStillWaitsForItsTwoSecondSilence()throws Exception{fixture.first="Título isolado";start();String gap="gap:"+service.cursor.pending.id;assertNotNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(0,service.part);assertEquals(gap,service.waitingGap);service.progress.onDone(gap);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(Arrays.asList(2000L),SpeechServiceTest.ManualTts.silences);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());}
 @Test public void aHeadingAtTheStartOfTheNextPageKeepsItsPauseBeforeTheBody()throws Exception{fixture.start("NOVO CAPÍTULO</p><p>Texto depois do título.");service=fixture.service;fixture.drain();String title=service.queuedPage.cursor.pending.id;service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(title,service.cursor.pending.id);assertEquals(2000,service.cursor.pending.pauseAfter);assertTrue(service.silences.contains("gap:"+title));assertTrue(service.cursor.queued.text.contains("Texto depois"));assertEquals(Arrays.asList(2000L),SpeechServiceTest.ManualTts.silences);}
 @Test public void onlineVoiceAlsoReceivesTheNextPageBeforeTheCurrentOneEnds()throws Exception{org.robolectric.shadows.ShadowTextToSpeech.addVoice(new Voice("pt-network-flow",new Locale("pt","PT"),500,200,true,Collections.emptySet()));new SpeechProfile("com.google.android.tts","pt-network-flow","pt",true,1).save(fixture.app.getSharedPreferences("seeky",0));android.net.ConnectivityManager cm=(android.net.ConnectivityManager)fixture.app.getSystemService(android.content.Context.CONNECTIVITY_SERVICE);android.net.Network network=cm.getActiveNetwork();assertNotNull(network);android.net.NetworkCapabilities capabilities=org.robolectric.shadows.ShadowNetworkCapabilities.newInstance();shadowOf(capabilities).addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET);shadowOf(cm).setNetworkCapabilities(network,capabilities);start();assertTrue(service.request.online);assertNotNull(service.queuedPage);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());assertEquals(Integer.valueOf(TextToSpeech.QUEUE_ADD),SpeechServiceTest.ManualTts.queues.get(1));}
 @Test public void aFailedFutureUtteranceFallsBackWithoutStoppingTheCurrentPage()throws Exception{start();String next=service.queuedPage.cursor.pending.id;service.progress.onError(next,TextToSpeech.ERROR_NETWORK);shadowOf(Looper.getMainLooper()).idle();assertNull(service.queuedPage);assertFalse(service.cursor.paused);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();fixture.drain();assertEquals(1,service.part);assertTrue(service.cursor.pending.text.contains("Segunda página"));}
 @Test public void threeShortPartsRemainInOrderWithOnlyTheInitialQueueFlush()throws Exception{fixture.third="Terceira página, o fim do livro.";start();service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();fixture.drain();assertEquals(1,service.part);assertNotNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(2,service.part);assertEquals(3,SpeechServiceTest.ManualTts.texts.size());assertTrue(SpeechServiceTest.ManualTts.texts.get(0).startsWith("Primeiro"));assertTrue(SpeechServiceTest.ManualTts.texts.get(1).startsWith("Segunda"));assertTrue(SpeechServiceTest.ManualTts.texts.get(2).startsWith("Terceira"));assertEquals(Arrays.asList(TextToSpeech.QUEUE_FLUSH,TextToSpeech.QUEUE_ADD,TextToSpeech.QUEUE_ADD),SpeechServiceTest.ManualTts.queues);}
 @Test public void disablingContinuousReadingDoesNotQueueAnotherPart()throws Exception{fixture.continuous=false;start();assertNull(service.queuedPage);assertEquals(1,SpeechServiceTest.ManualTts.texts.size());service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertNull(service.request);assertEquals(0,service.part);}
 @Test public void studyProgressChangesDoNotDiscardThePreparedPage()throws Exception{start();ReadAloudService.QueuedPage ready=service.queuedPage;StudyState.bump(fixture.app);shadowOf(Looper.getMainLooper()).idle();assertSame(ready,service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());}
 @Test public void editingTheFuturePageInvalidatesQueuedSpeechAndUsesTheUpdatedNotebook()throws Exception{start();ReadAloudService.Prefetched prepared=service.prefetched;try(ReaderStore notes=new ReaderStore(fixture.app)){notes.save(fixture.uri.toString(),1,prepared.value,new StudyText("Página corrigida pelo estudante."));}fixture.drain();assertNotNull(service.queuedPage);assertTrue(service.queuedPage.cursor.text.contains("corrigida"));service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertTrue(service.cursor.pending.text.contains("corrigida"));}
 @Test public void trailingNonBreakingSpacesDoNotPreventTheNextPageFromBeingQueued()throws Exception{fixture.first="Uma frase completa na página.&#160;&#160;";start();assertNotNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());}
 @Test public void pdfPagesWithSavedOcrAlsoQueueVoiceBeforeThePageBoundary()throws Exception{try(com.tom_roush.pdfbox.pdmodel.PDDocument pdf=new com.tom_roush.pdfbox.pdmodel.PDDocument()){pdf.addPage(new com.tom_roush.pdfbox.pdmodel.PDPage());pdf.addPage(new com.tom_roush.pdfbox.pdmodel.PDPage());pdf.save(SpeechPrefetchTest.book);}String hash=StudyFiles.hash(SpeechPrefetchTest.book);OcrCache.save(fixture.app,fixture.uri.toString(),0,hash,"Primeira página PDF reconhecida.");OcrCache.save(fixture.app,fixture.uri.toString(),1,hash,"Segunda página PDF corrigida.");fixture.controller=Robolectric.buildService(ReadAloudService.class).create();service=fixture.service=fixture.controller.get();shadowOf(service.audio).setNextFocusRequestResponse(android.media.AudioManager.AUDIOFOCUS_REQUEST_GRANTED);service.onStartCommand(new android.content.Intent().setAction(ReadAloudService.START).setDataAndType(fixture.uri,"application/pdf").putExtra("name","Livro.pdf"),0,1);fixture.drain();SpeechServiceTest.ready(service);fixture.drain();assertEquals(2,service.total);assertNotNull(service.queuedPage);assertTrue(SpeechServiceTest.ManualTts.texts.get(1).contains("PDF corrigida"));service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.part);assertEquals(Arrays.asList(TextToSpeech.QUEUE_FLUSH,TextToSpeech.QUEUE_ADD),SpeechServiceTest.ManualTts.queues);}
 @Test public void aVoiceWithoutSilentQueueSupportStillWaitsBeforeTheNextPart()throws Exception{SpeechServiceTest.ManualTts.silentFails=true;fixture.first="Título isolado";start();assertNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();shadowOf(Looper.getMainLooper()).idleFor(1999,TimeUnit.MILLISECONDS);assertEquals(0,service.part);assertEquals(1,SpeechServiceTest.ManualTts.texts.size());shadowOf(Looper.getMainLooper()).idleFor(1,TimeUnit.MILLISECONDS);fixture.drain();assertEquals(1,service.part);assertTrue(service.cursor.pending.text.contains("Segunda página"));}
 @Test public void anEmptyPartIsSkippedWithoutSpeakingEmptyTextOrRepeatingThePreviousPage()throws Exception{fixture.third="Última página depois da parte vazia.";fixture.start("");service=fixture.service;fixture.drain();assertNull(service.queuedPage);service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();fixture.drain();assertEquals(2,service.part);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());assertTrue(service.cursor.pending.text.contains("Última página"));}
}
